import React, { useState } from 'react';
import {
  Box,
  TextField,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  List,
  ListItem,
  ListItemText,
  Paper,
  Typography,
  Divider,
  MenuItem,
  FormControl,
  InputLabel,
  Select,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import AddIcon from '@mui/icons-material/Add';
import { useCurrency } from '../CurrencyContext';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import dayjs from 'dayjs';

const PaymentList = ({ payments, loans, debts, onAdd, onEdit, onDelete }) => {
  const { formatCurrency } = useCurrency();
  const [open, setOpen] = useState(false);
  const [editingPayment, setEditingPayment] = useState(null);
  const [formData, setFormData] = useState({
    targetType: 'loan', // 'loan' or 'debt'
    targetId: '',
    targetName: '',
    amount: '',
    date: dayjs(),
  });

  // Combine loans and debts for selection
  const availableTargets = [
    ...loans.map(loan => {
      const principal = loan.amount;
      const interest = loan.interestRate ? (principal * loan.interestRate) / 100 : 0;
      const totalAmount = principal + interest;
      return {
        ...loan,
        type: 'loan',
        displayAmount: totalAmount,
        displayName: loan.interestRate 
          ? `${loan.name} (Loan - ${loan.interestRate}% interest)`
          : `${loan.name} (Loan)`
      };
    }),
    ...debts.map(debt => ({
      ...debt,
      type: 'debt',
      displayAmount: debt.amount,
      displayName: `${debt.name} (Debt)`
    })),
  ];

  const handleOpen = (payment = null) => {
    if (payment) {
      setEditingPayment(payment);
      setFormData({
        targetType: payment.targetType,
        targetId: payment.targetId,
        targetName: payment.targetName,
        amount: payment.amount.toString(),
        date: payment.date ? dayjs(payment.date.toDate()) : dayjs(),
      });
    } else {
      setEditingPayment(null);
      setFormData({
        targetType: 'loan',
        targetId: '',
        targetName: '',
        amount: '',
        date: dayjs(),
      });
    }
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setEditingPayment(null);
    setFormData({
      targetType: 'loan',
      targetId: '',
      targetName: '',
      amount: '',
      date: dayjs(),
    });
  };

  const handleTargetChange = (targetId) => {
    const selected = availableTargets.find(t => t.id === targetId);
    if (selected) {
      setFormData({
        ...formData,
        targetId: selected.id,
        targetName: selected.name,
        targetType: selected.type,
        amount: selected.displayAmount.toString(), // Pre-fill with full amount including interest
      });
    }
  };

  const handleSubmit = () => {
    const amount = parseFloat(formData.amount);

    if (!formData.targetId || !formData.targetName || isNaN(amount) || amount <= 0) {
      alert('Please fill in all required fields with valid values');
      return;
    }

    const paymentData = {
      targetType: formData.targetType,
      targetId: formData.targetId,
      targetName: formData.targetName,
      amount: amount,
      date: formData.date.toDate(),
    };

    if (editingPayment) {
      onEdit(editingPayment.id, paymentData);
    } else {
      onAdd(paymentData);
    }

    handleClose();
  };

  return (
    <Paper elevation={2} sx={{ p: 2, height: '100%' }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6" component="h2">
          Payments Made
        </Typography>
        <Button
          variant="contained"
          size="small"
          startIcon={<AddIcon />}
          onClick={() => handleOpen()}
          disabled={availableTargets.length === 0}
        >
          Add
        </Button>
      </Box>
      <Divider sx={{ mb: 2 }} />
      
      {availableTargets.length === 0 ? (
        <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', py: 2 }}>
          Add loans or debts first to record payments
        </Typography>
      ) : (
        <List>
          {payments.length === 0 ? (
            <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', py: 2 }}>
              No payments recorded yet
            </Typography>
          ) : (
            payments.map((payment) => (
              <ListItem
                key={payment.id}
                secondaryAction={
                  <Box>
                    <IconButton edge="end" aria-label="edit" onClick={() => handleOpen(payment)} sx={{ mr: 1 }}>
                      <EditIcon />
                    </IconButton>
                    <IconButton edge="end" aria-label="delete" onClick={() => onDelete(payment.id)}>
                      <DeleteIcon />
                    </IconButton>
                  </Box>
                }
                sx={{ bgcolor: 'background.default', mb: 1, borderRadius: 1 }}
              >
                <ListItemText
                  primary={`Payment to: ${payment.targetName}`}
                  secondary={
                    <>
                      <Typography variant="body2" color="success.main">
                        {formatCurrency(payment.amount)}
                      </Typography>
                      {payment.date && (
                        <Typography variant="caption" display="block" color="text.secondary">
                          {dayjs(payment.date.toDate()).format('MMM DD, YYYY')}
                        </Typography>
                      )}
                    </>
                  }
                />
              </ListItem>
            ))
          )}
        </List>
      )}

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>{editingPayment ? 'Edit' : 'Record'} Payment</DialogTitle>
        <DialogContent>
          <FormControl fullWidth sx={{ mt: 1, mb: 2 }}>
            <InputLabel id="target-select-label">Pay Towards</InputLabel>
            <Select
              labelId="target-select-label"
              value={formData.targetId}
              label="Pay Towards"
              onChange={(e) => handleTargetChange(e.target.value)}
              disabled={!!editingPayment}
            >
              {availableTargets.map((target) => (
                <MenuItem key={target.id} value={target.id}>
                  {target.displayName} - {formatCurrency(target.displayAmount)}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          
          <TextField
            margin="dense"
            label="Payment Amount"
            type="number"
            fullWidth
            variant="outlined"
            value={formData.amount}
            onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
            helperText="Enter full amount or partial payment"
            sx={{ mb: 2 }}
          />
          
          <LocalizationProvider dateAdapter={AdapterDayjs}>
            <DatePicker
              label="Payment Date"
              value={formData.date}
              onChange={(newDate) => setFormData({ ...formData, date: newDate })}
              slotProps={{
                textField: {
                  fullWidth: true,
                  variant: 'outlined',
                },
              }}
            />
          </LocalizationProvider>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
          <Button onClick={handleSubmit} variant="contained">
            {editingPayment ? 'Update' : 'Record Payment'}
          </Button>
        </DialogActions>
      </Dialog>
    </Paper>
  );
};

export default PaymentList;
