import React, { useState } from 'react';
import {
  Box,
  TextField,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  List,
  ListItem,
  ListItemText,
  Paper,
  Typography,
  Divider,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import AddIcon from '@mui/icons-material/Add';
import { useCurrency } from '../CurrencyContext';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import dayjs from 'dayjs';

const ItemList = ({ title, items, onAdd, onEdit, onDelete, showInterest = false }) => {
  const { formatCurrency } = useCurrency();
  const [open, setOpen] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    amount: '',
    interestRate: '',
    date: dayjs(),
  });

  const handleOpen = (item = null) => {
    if (item) {
      setEditingItem(item);
      setFormData({
        name: item.name,
        amount: item.amount.toString(),
        interestRate: item.interestRate ? item.interestRate.toString() : '',
        date: item.date ? dayjs(item.date.toDate()) : dayjs(),
      });
    } else {
      setEditingItem(null);
      setFormData({ name: '', amount: '', interestRate: '', date: dayjs() });
    }
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setEditingItem(null);
    setFormData({ name: '', amount: '', interestRate: '', date: dayjs() });
  };

  const handleSubmit = () => {
    const amount = parseFloat(formData.amount);
    const interestRate = formData.interestRate ? parseFloat(formData.interestRate) : 0;

    if (!formData.name || isNaN(amount)) {
      alert('Please fill in all required fields');
      return;
    }

    const itemData = {
      name: formData.name,
      amount: amount,
      date: formData.date.toDate(),
      ...(showInterest && { interestRate: interestRate }),
    };

    if (editingItem) {
      onEdit(editingItem.id, itemData);
    } else {
      onAdd(itemData);
    }

    handleClose();
  };

  return (
    <Paper elevation={2} sx={{ p: 2, height: '100%' }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6" component="h2">
          {title}
        </Typography>
        <Button
          variant="contained"
          size="small"
          startIcon={<AddIcon />}
          onClick={() => handleOpen()}
        >
          Add
        </Button>
      </Box>
      <Divider sx={{ mb: 2 }} />
      <List>
        {items.length === 0 ? (
          <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', py: 2 }}>
            No items added yet
          </Typography>
        ) : (
          items.map((item) => (
            <ListItem
              key={item.id}
              secondaryAction={
                <Box>
                  <IconButton edge="end" aria-label="edit" onClick={() => handleOpen(item)} sx={{ mr: 1 }}>
                    <EditIcon />
                  </IconButton>
                  <IconButton edge="end" aria-label="delete" onClick={() => onDelete(item.id)}>
                    <DeleteIcon />
                  </IconButton>
                </Box>
              }
              sx={{ bgcolor: 'background.default', mb: 1, borderRadius: 1 }}
            >
              <ListItemText
                primary={item.name}
                secondary={
                  <>
                    {showInterest && item.interestRate
                      ? `${formatCurrency(item.amount)} (${item.interestRate}% interest)`
                      : formatCurrency(item.amount)}
                    {item.date && (
                      <Typography variant="caption" display="block" color="text.secondary">
                        {dayjs(item.date.toDate()).format('MMM DD, YYYY')}
                      </Typography>
                    )}
                  </>
                }
              />
            </ListItem>
          ))
        )}
      </List>

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>{editingItem ? 'Edit' : 'Add'} {title}</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="Name"
            type="text"
            fullWidth
            variant="outlined"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            sx={{ mb: 2, mt: 1 }}
          />
          <TextField
            margin="dense"
            label="Amount"
            type="number"
            fullWidth
            variant="outlined"
            value={formData.amount}
            onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
            sx={{ mb: 2 }}
          />
          {showInterest && (
            <TextField
              margin="dense"
              label="Interest Rate (%)"
              type="number"
              fullWidth
              variant="outlined"
              value={formData.interestRate}
              onChange={(e) => setFormData({ ...formData, interestRate: e.target.value })}
              inputProps={{ step: '0.1' }}
              sx={{ mb: 2 }}
            />
          )}
          <LocalizationProvider dateAdapter={AdapterDayjs}>
            <DatePicker
              label="Date"
              value={formData.date}
              onChange={(newDate) => setFormData({ ...formData, date: newDate })}
              slotProps={{
                textField: {
                  fullWidth: true,
                  variant: 'outlined',
                },
              }}
            />
          </LocalizationProvider>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
          <Button onClick={handleSubmit} variant="contained">
            {editingItem ? 'Update' : 'Add'}
          </Button>
        </DialogActions>
      </Dialog>
    </Paper>
  );
};

export default ItemList;
